import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { randomBytes } from 'node:crypto';

export const LIMITS = { title: 200, author: 200, notes: 10_000 };

// Checks and normalizes form input for a new book.
// Returns { value } on success or { errors } keyed by field name.
export function validateBook(input) {
  const value = {
    title: String(input.title ?? '').trim(),
    author: String(input.author ?? '').trim(),
    notes: String(input.notes ?? '').replace(/\r\n/g, '\n').trim(),
  };
  const errors = {};
  if (!value.title) errors.title = 'Title is required.';
  for (const [field, max] of Object.entries(LIMITS)) {
    if (value[field].length > max) errors[field] = `Keep this under ${max} characters.`;
  }
  return Object.keys(errors).length ? { errors } : { value };
}

// Opens a JSON-file-backed book store. Books are kept in memory and the whole
// list is rewritten on every change (temp file + rename, so a crash mid-write
// can't leave a half-written file behind).
export async function openStore(file) {
  let books = await load(file);
  let queue = Promise.resolve();

  // Run mutations one at a time so concurrent requests can't interleave writes.
  function serialize(fn) {
    const result = queue.then(fn);
    queue = result.catch(() => {});
    return result;
  }

  // Only swap in the new list once it's safely on disk.
  async function commit(next) {
    await mkdir(dirname(file), { recursive: true });
    const tmp = `${file}.tmp`;
    await writeFile(tmp, JSON.stringify(next, null, 2) + '\n');
    await rename(tmp, file);
    books = next;
  }

  return {
    list() {
      return books.slice();
    },

    get(id) {
      return books.find((book) => book.id === id);
    },

    add(input) {
      const { value, errors } = validateBook(input);
      if (errors) throw Object.assign(new Error('Invalid book'), { errors });
      return serialize(async () => {
        const book = {
          id: newId(),
          ...value,
          status: 'reading',
          addedAt: new Date().toISOString(),
          finishedAt: null,
        };
        await commit([...books, book]);
        return book;
      });
    },

    // Returns the updated book, or undefined if there's no book with that id.
    finish(id) {
      return serialize(async () => {
        const book = books.find((b) => b.id === id);
        if (!book || book.status === 'finished') return book;
        const updated = { ...book, status: 'finished', finishedAt: new Date().toISOString() };
        await commit(books.map((b) => (b === book ? updated : b)));
        return updated;
      });
    },
  };
}

async function load(file) {
  let text;
  try {
    text = await readFile(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  // Refuse to start on a corrupt file rather than silently overwriting it.
  const data = JSON.parse(text);
  if (!Array.isArray(data)) throw new Error(`${file} should contain a JSON array of books`);
  return data;
}

function newId() {
  return randomBytes(6).toString('base64url');
}

