import { LIMITS } from './store.js';

const ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

export function escape(value) {
  return String(value ?? '').replace(/[&<>"']/g, (ch) => ESCAPES[ch]);
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  a { color: #1a5fb4; }
  h1 a { color: inherit; text-decoration: none; }
  ul { padding: 0; list-style: none; }
  li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .muted { color: #666; }
  .empty { color: #666; font-style: italic; }
  form.add { display: grid; gap: .75rem; }
  label { display: grid; gap: .25rem; font-weight: 600; }
  input, textarea { font: inherit; padding: .4rem; border: 1px solid #bbb; border-radius: 4px; font-weight: normal; }
  button { font: inherit; padding: .3rem .8rem; cursor: pointer; }
  .error { color: #b00020; font-weight: normal; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: 1rem; border-radius: 4px; }
</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function finishButton(book, from) {
  if (book.status === 'finished') return '';
  return `<form method="post" action="/books/${escape(book.id)}/finish">
  <input type="hidden" name="from" value="${from}">
  <button type="submit">Mark finished</button>
</form>`;
}

function bookItem(book) {
  const meta = book.status === 'finished'
    ? `${escape(book.author || 'Unknown author')} · finished ${formatDate(book.finishedAt)}`
    : escape(book.author || 'Unknown author');
  return `<li>
  <span><a href="/books/${escape(book.id)}">${escape(book.title)}</a> <span class="muted">— ${meta}</span></span>
  ${finishButton(book, 'home')}
</li>`;
}

function bookList(books, emptyText) {
  if (!books.length) return `<p class="empty">${emptyText}</p>`;
  return `<ul>\n${books.map(bookItem).join('\n')}\n</ul>`;
}

function field(name, label, values, errors, { multiline = false, required = false } = {}) {
  const attrs = `id="${name}" name="${name}" maxlength="${LIMITS[name]}"${required ? ' required' : ''}`;
  const control = multiline
    ? `<textarea ${attrs} rows="4">${escape(values[name])}</textarea>`
    : `<input ${attrs} value="${escape(values[name])}">`;
  const error = errors[name] ? `<span class="error">${escape(errors[name])}</span>` : '';
  return `<label for="${name}">${label}${control}${error}</label>`;
}

export function homePage({ books, values = {}, errors = {} }) {
  const reading = books
    .filter((b) => b.status !== 'finished')
    .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  return layout('My books', `
<h2>Currently reading</h2>
${bookList(reading, 'Nothing on the go right now.')}

<h2>Finished</h2>
${bookList(finished, 'No finished books yet.')}

<h2>Add a book</h2>
<form class="add" method="post" action="/books">
  ${field('title', 'Title', values, errors, { required: true })}
  ${field('author', 'Author', values, errors)}
  ${field('notes', 'Notes', values, errors, { multiline: true })}
  <div><button type="submit">Add book</button></div>
</form>`);
}

export function bookPage(book, shareUrl) {
  const status = book.status === 'finished'
    ? `Finished ${formatDate(book.finishedAt)}`
    : `Reading since ${formatDate(book.addedAt)}`;
  const notes = book.notes
    ? `<div class="notes">${escape(book.notes)}</div>`
    : '<p class="empty">No notes.</p>';

  return layout(book.title, `
<h2>${escape(book.title)}</h2>
<p>by ${escape(book.author || 'Unknown author')}</p>
<p class="muted">${status}</p>
${finishButton(book, 'book')}

<h3>Notes</h3>
${notes}

<p><label for="share">Link to this book <input id="share" readonly value="${escape(shareUrl)}"></label></p>
<p><a href="/">← All books</a></p>`);
}

export function messagePage(title, message) {
  return layout(title, `<h2>${escape(title)}</h2>\n<p>${escape(message)}</p>\n<p><a href="/">← All books</a></p>`);
}

