import { bookPage, homePage, messagePage } from './views.js';

const MAX_BODY_BYTES = 64 * 1024;

const SECURITY_HEADERS = {
  'Content-Security-Policy':
    "default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'",
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'same-origin',
};

// Builds the request handler. `publicUrl` (e.g. "https://books.example.com") is
// used for share links; without it they're built from the request's Host header.
export function createApp(store, { publicUrl } = {}) {
  async function route(req, res) {
    const { pathname } = new URL(req.url, 'http://localhost');
    const method = req.method === 'HEAD' ? 'GET' : req.method;
    let match;

    if (pathname === '/') {
      if (method !== 'GET') return methodNotAllowed(res, 'GET, HEAD');
      return html(res, 200, homePage({ books: store.list() }));
    }

    if (pathname === '/books') {
      if (method !== 'POST') return methodNotAllowed(res, 'POST');
      const form = await readForm(req);
      try {
        await store.add(form);
      } catch (err) {
        if (!err.errors) throw err;
        return html(res, 400, homePage({ books: store.list(), values: form, errors: err.errors }));
      }
      return redirect(res, '/');
    }

    if ((match = pathname.match(/^\/books\/([\w-]+)$/))) {
      if (method !== 'GET') return methodNotAllowed(res, 'GET, HEAD');
      const book = store.get(match[1]);
      if (!book) return notFound(res);
      return html(res, 200, bookPage(book, shareUrl(req, pathname)));
    }

    if ((match = pathname.match(/^\/books\/([\w-]+)\/finish$/))) {
      if (method !== 'POST') return methodNotAllowed(res, 'POST');
      const form = await readForm(req);
      const book = await store.finish(match[1]);
      if (!book) return notFound(res);
      return redirect(res, form.from === 'book' ? `/books/${book.id}` : '/');
    }

    return notFound(res);
  }

  function shareUrl(req, pathname) {
    if (publicUrl) return publicUrl.replace(/\/+$/, '') + pathname;
    const proto = req.headers['x-forwarded-proto'] === 'https' ? 'https' : 'http';
    return `${proto}://${req.headers.host ?? 'localhost'}${pathname}`;
  }

  return async function handler(req, res) {
    try {
      await route(req, res);
    } catch (err) {
      if (err.status === 413) return html(res, 413, messagePage('Too much text', 'That form was too large to save.'));
      console.error(err);
      if (res.headersSent) return res.end();
      html(res, 500, messagePage('Something went wrong', 'The server hit an error. Please try again.'));
    }
  };
}

async function readForm(req) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw Object.assign(new Error('Body too large'), { status: 413 });
    chunks.push(chunk);
  }
  return Object.fromEntries(new URLSearchParams(Buffer.concat(chunks).toString('utf8')));
}

function html(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', ...SECURITY_HEADERS });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function notFound(res) {
  html(res, 404, messagePage('Book not found', "There's no book at this address. It may have been a mistyped link."));
}

function methodNotAllowed(res, allow) {
  res.writeHead(405, { Allow: allow, 'Content-Type': 'text/plain; charset=utf-8' });
  res.end('Method not allowed');
}

