import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createServer } from 'node:http';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createApp } from '../src/app.js';
import { openStore } from '../src/store.js';

let dir, file;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'));
  file = join(dir, 'books.json');
});

afterEach(async () => {
  await rm(dir, { recursive: true, force: true });
});

describe('store', () => {
  it('starts empty when there is no file yet', async () => {
    const store = await openStore(file);
    expect(store.list()).toEqual([]);
  });

  it('keeps books across a restart', async () => {
    const store = await openStore(file);
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice.' });
    await store.finish(book.id);

    const reopened = await openStore(file);
    expect(reopened.get(book.id)).toMatchObject({
      title: 'Dune',
      author: 'Frank Herbert',
      notes: 'Spice.',
      status: 'finished',
    });
    expect(reopened.get(book.id).finishedAt).toBeTruthy();
  });

  it('requires a title', async () => {
    const store = await openStore(file);
    await expect(store.add({ title: '  ', author: 'Someone' })).rejects.toMatchObject({
      errors: { title: expect.any(String) },
    });
    expect(store.list()).toEqual([]);
  });

  it('does not lose books when many are added at once', async () => {
    const store = await openStore(file);
    await Promise.all(Array.from({ length: 20 }, (_, i) => store.add({ title: `Book ${i}` })));
    const reopened = await openStore(file);
    expect(reopened.list()).toHaveLength(20);
  });

  it('refuses to start on a corrupt file instead of overwriting it', async () => {
    await writeFile(file, '{ not json');
    await expect(openStore(file)).rejects.toThrow();
    expect(await readFile(file, 'utf8')).toBe('{ not json');
  });

  it('returns undefined when finishing an unknown book', async () => {
    const store = await openStore(file);
    expect(await store.finish('nope')).toBeUndefined();
  });
});

describe('app', () => {
  let server, base, store;

  beforeEach(async () => {
    store = await openStore(file);
    server = createServer(createApp(store));
    await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
    base = `http://127.0.0.1:${server.address().port}`;
  });

  afterEach(async () => {
    await new Promise((resolve) => server.close(resolve));
  });

  const post = (path, fields) =>
    fetch(base + path, { method: 'POST', body: new URLSearchParams(fields), redirect: 'manual' });

  function section(html, heading) {
    const start = html.indexOf(`<h2>${heading}</h2>`);
    const end = html.indexOf('<h2>', start + 1);
    return html.slice(start, end === -1 ? undefined : end);
  }

  it('adds a book, shows it as reading, then as finished', async () => {
    const res = await post('/books', { title: 'Middlemarch', author: 'George Eliot', notes: '' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    let html = await (await fetch(base + '/')).text();
    expect(section(html, 'Currently reading')).toContain('Middlemarch');
    expect(section(html, 'Finished')).not.toContain('Middlemarch');

    const [book] = store.list();
    const finish = await post(`/books/${book.id}/finish`, { from: 'home' });
    expect(finish.status).toBe(303);

    html = await (await fetch(base + '/')).text();
    expect(section(html, 'Currently reading')).not.toContain('Middlemarch');
    expect(section(html, 'Finished')).toContain('Middlemarch');
  });

  it('shows a book page with title, author, notes and a share link', async () => {
    const book = await store.add({ title: 'Emma', author: 'Jane Austen', notes: 'Line one\nLine two' });
    const res = await fetch(`${base}/books/${book.id}`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('Emma');
    expect(html).toContain('Jane Austen');
    expect(html).toContain('Line one\nLine two');
    expect(html).toContain(`value="${base}/books/${book.id}"`);
  });

  it('uses the configured public URL for share links', async () => {
    const other = createServer(createApp(store, { publicUrl: 'https://books.example.com/' }));
    await new Promise((resolve) => other.listen(0, '127.0.0.1', resolve));
    const book = await store.add({ title: 'Emma' });
    const html = await (await fetch(`http://127.0.0.1:${other.address().port}/books/${book.id}`)).text();
    await new Promise((resolve) => other.close(resolve));
    expect(html).toContain(`value="https://books.example.com/books/${book.id}"`);
  });

  it('redirects back to the book page when finishing from there', async () => {
    const book = await store.add({ title: 'Emma' });
    const res = await post(`/books/${book.id}/finish`, { from: 'book' });
    expect(res.headers.get('location')).toBe(`/books/${book.id}`);
  });

  it('escapes user-entered text', async () => {
    const book = await store.add({ title: '<script>alert(1)</script>', notes: '"><img src=x onerror=alert(1)>' });
    const page = await (await fetch(`${base}/books/${book.id}`)).text();
    const home = await (await fetch(base + '/')).text();
    for (const html of [page, home]) {
      expect(html).not.toContain('<script>alert');
      expect(html).not.toContain('<img src=x');
    }
  });

  it('re-shows the form with an error and keeps the input when the title is missing', async () => {
    const res = await post('/books', { title: '', author: 'Kept Author' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Title is required.');
    expect(html).toContain('value="Kept Author"');
    expect(store.list()).toEqual([]);
  });

  it('returns 404 for unknown books', async () => {
    expect((await fetch(`${base}/books/doesnotexist`)).status).toBe(404);
    expect((await post('/books/doesnotexist/finish', {})).status).toBe(404);
  });

  it('rejects oversized form submissions', async () => {
    const res = await post('/books', { title: 'Big', notes: 'x'.repeat(100_000) });
    expect(res.status).toBe(413);
    expect(store.list()).toEqual([]);
  });
});

